mapper.sql:
where p.IS_DELETE = '0'
and p.EMPLOYEE_NAME like concat('%',#{employeeName},'%')
and p.EMPLOYEE_CODE = #{employeeCode}
and p.DUTY_DEPT_CODE like concat('%',#{dutyDeptCode})
and p.DUTY_DEPT_NAME like concat('%',#{dutyDeptName},'%')
and p.DEVICE_CODE = #{deviceCode}

mapper.select:
select s.*,
CONCAT(#{bpmUrlPre},'&formInstanceId=',s.PROCESS_ID,'&processId=',s.BPM_FLOW_ID) bpm_url
from ( select p.EMPLOYEE_CODE, max(p.EMPLOYEE_NAME) EMPLOYEE_NAME, max(e.position_name) position_name, p.DUTY_DEPT_NAME, p.DUTY_DEPT_CODE, max(p.EMPOSER_NUM) EMPOSER_NUM, group_concat(p.DEVICE_NAME order by p.DEVICE_NAME separator ',') as device_name, max(p.BUILD_NUM) BUILD_NUM, max(p.CREATE_TIME) CREATE_TIME, max(p.PROCESS_CODE) PROCESS_CODE, max(m.BPM_FLOW_ID) BPM_FLOW_ID, max(p.PROCESS_ID) PROCESS_ID from safety_build_power p left join safety_build_manage_process m on p.PROCESS_ID = m.id left join safety_employee_message e on p.EMPLOYEE_CODE = e.emp_no and e.status = 'NORMAL'
GROUP BY p.EMPLOYEE_CODE, p.DUTY_DEPT_NAME, p.DUTY_DEPT_CODE )s order by s.CREATE_TIME desc
limit ${offset}, ${limit}
limit ${limit}

mapper.update:
update safety_build_power
set
    UPDATE_TIME = now()

        ,BUILD_NUM = #{buildNum}


        ,EMPOSER_NUM = #{emposerNum}

where
    IS_DELETE = '0'
    and DUTY_DEPT_CODE = #{dutyDeptCode}

mapper.select:
select p.*,m.position_code,m.position_name,m.org_code from safety_build_power p left join safety_employee_message m on p.EMPLOYEE_CODE = m.emp_no and m.status = 'NORMAL' where p.EMPLOYEE_CODE in
#{ll}
and p.IS_DELETE = '0' order by p.UPDATE_TIME desc

select code,name,org_code_path,DUTY_DEPT_CODE,duty_dept_name from (select sgi.code ,sgi.name,sgi.org_code_path ,p.DUTY_DEPT_CODE,p.duty_dept_name, length (p.DUTY_DEPT_CODE) DUTY_LENGTH from safety_group_info sgi join (select distinct sbp.DUTY_DEPT_CODE, sbp.DUTY_DEPT_NAME from safety_build_power sbp where sbp.IS_DELETE = 0 and sbp.DUTY_DEPT_CODE != '') p on sgi.org_code_path like CONCAT( p.DUTY_DEPT_CODE, '%') where 1 = 1 and sgi.code in
#{item}
) cur where (code,duty_length) in ( select code, max(DUTY_LENGTH) DUTY_LENGTH from (select sgi.code ,sgi.org_code_path ,p.DUTY_DEPT_CODE,length (p.DUTY_DEPT_CODE) DUTY_LENGTH from safety_group_info sgi join (select distinct sbp.DUTY_DEPT_CODE,sbp.DUTY_DEPT_NAME from safety_build_power sbp where sbp.IS_DELETE = 0 and sbp.DUTY_DEPT_CODE != '' ) p on sgi.org_code_path like CONCAT( p.DUTY_DEPT_CODE, '%') where 1 = 1 and sgi.code in
#{item}
) cur group by code)

select
from safety.safety_build_power sbp where IS_DELETE = 0 and sbp.id in (select min(id) from safety.safety_build_power group by DUTY_DEPT_CODE)
and DUTY_DEPT_CODE in
